INSTR_LABELS = {
    Instruction.PAUSE:   ("Pause",      "⏸"),
    Instruction.DEFEND:  ("Defend",     "🛡"),
    Instruction.HARVEST: ("Harvest",    "🍆"),
    Instruction.GIVE:    ("Give",       "🎁"),
    Instruction.SETTLE:  ("Settle",     "🏰"),
    Instruction.FORWARD: ("Forward",    "→"),
    Instruction.ROT_L:   ("Turn Left",  "↺"),
    Instruction.ROT_R:   ("Turn Right", "↻"),
}


def _instr_glyph(instr: Instruction, flag: CountryFlag, size=26):
    """Inline SVG glyph for one instruction, themed from a CountryFlag."""
    g = DiagramGlyphs(flag, size=size * 0.55)
    cx, cy = size / 2, size / 2
    c = MapCord(cx, cy)

    if instr == Instruction.FORWARD:
        body = (f'<line x1="{cx-size*0.28:.1f}" y1="{cy:.1f}" '
                f'x2="{cx+size*0.2:.1f}" y2="{cy:.1f}" '
                f'stroke="{g.color}" stroke-width="2.5" stroke-linecap="round"/>'
                f'<polygon points="{cx+size*0.28:.1f},{cy:.1f} '
                f'{cx+size*0.12:.1f},{cy-size*0.13:.1f} '
                f'{cx+size*0.12:.1f},{cy+size*0.13:.1f}" fill="{g.color}"/>')
    else:
        fn = {
            Instruction.PAUSE:   g.pause,
            Instruction.DEFEND:  g.shield,
            Instruction.HARVEST: g.sheaf,
            Instruction.GIVE:    g.gift,
            Instruction.SETTLE:  g.house,
            Instruction.ROT_L:   lambda c: g.rot_arrow(c, clockwise=False),
            Instruction.ROT_R:   lambda c: g.rot_arrow(c, clockwise=True),
        }.get(instr)
        body = fn(c) if fn else ""

    # Build a mini SVGBuilder to get the style block
    canvas = SVGBuilder()
    canvas.width = size
    canvas.height = size
    g.register_styles(canvas)
    canvas.adjust("body", body)
    return NotStr(canvas.generate())




