# ── Badge styles via StyleCSS ────────────────────────────

_INSTR_BADGE_COLORS = {
    Instruction.PAUSE:   "#94a3b8",
    Instruction.DEFEND:  "#ef4444",
    Instruction.HARVEST: "#22c55e",
    Instruction.GIVE:    "#a855f7",
    Instruction.SETTLE:  "#f59e0b",
    Instruction.FORWARD: "#3b82f6",
    Instruction.ROT_L:   "#64748b",
    Instruction.ROT_R:   "#64748b",
}

def _badge_styles(flag: CountryFlag = None) -> tuple[list[StyleCSS], dict[Instruction, str]]:
    """Build StyleCSS objects for instruction badges. Returns (styles, name_map)."""
    colors = dict(_INSTR_BADGE_COLORS)
    if flag:
        colors[Instruction.FORWARD] = flag.darkPrimary
        colors[Instruction.ROT_L]   = flag.darkPrimary
        colors[Instruction.ROT_R]   = flag.darkPrimary
        colors[Instruction.HARVEST] = flag.comp
        colors[Instruction.GIVE]    = flag.primary

    styles, names = [], {}
    for instr, color in colors.items():
        cls_name = f"ibadge_{instr.name.lower()}"
        styles.append(StyleCSS(cls_name,
            background=f"{color}22", border=f"1px solid {color}",
            border_radius="4px", padding="2px 6px", font_size="11px",
            color=color, margin="2px", display="inline-block"))
        names[instr] = cls_name
    return styles, names


