_ACTION_GLYPH = {
    Instruction.PAUSE:   lambda g, c: g.pause(c),
    Instruction.DEFEND:  lambda g, c: g.shield(c),
    Instruction.HARVEST: lambda g, c: g.sheaf(c),
    Instruction.GIVE:    lambda g, c: g.gift(c),
    Instruction.SETTLE:  lambda g, c: g.house(c),
    Instruction.ROT_L:   lambda g, c: g.rot_arrow(c, clockwise=False),
    Instruction.ROT_R:   lambda g, c: g.rot_arrow(c, clockwise=True),
}

def piece_plan_overlay(piece: Piece, grid: HexGrid,
                       steps: list[PieceStep] = None,
                       c2f: dict = None,
                       num_turns: int = 12,
                       elevations: np.ndarray = None,
                       countries: np.ndarray = None) -> str:
    if steps is None:
        if elevations is None: return ""
        steps = piece.simulate(grid, elevations, num_turns=num_turns,
                               countries=countries)
    if not steps: return ""

    flag = piece.flag
    if not flag: return ""

    svg, N = "", len(grid.hexes)
    r = grid.radius
    g = DiagramGlyphs(flag, size=r * 0.45)
    g.register_styles(grid.builder)

    arrow_style = StyleCSS(
        f"plan_arr_{piece.id[:8]}",
        stroke=flag.primary, stroke_width=max(1, r * 0.08),
        fill="none", opacity="0.7",
        stroke_dasharray=f"{r*0.25:.0f},{r*0.12:.0f}",
    )
    grid.builder.add_style(arrow_style)

    # ── Start marker ──
    start = _map_point(piece.location, c2f)
    if 0 <= start < N:
        svg += piece.draw_svg(grid, hex_idx=start)
        svg += g.start_marker(grid.hexes[start].center)

    # ── Each step ──
    prev_idx = start
    for step in steps:
        idx = _map_point(step.hex_idx, c2f)
        if idx < 0 or idx >= N:
            prev_idx = idx
            continue
        c = grid.hexes[idx].center

        if step.instruction == Instruction.FORWARD and not step.blocked:
            if 0 <= prev_idx < N and prev_idx != idx:
                svg += grid.arrow(prev_idx, idx, style=arrow_style, factor=0.3)
            svg += piece.draw_ghost(grid, idx)
        elif step.blocked:
            svg += g.blocked_x(c)
        else:
            fn = _ACTION_GLYPH.get(step.instruction)
            if fn: svg += fn(g, c)

        prev_idx = idx

    # ── Range labels ──
    for hex_idx, t0, t1 in _turn_end_labels(steps):
        idx = _map_point(hex_idx, c2f)
        if 0 <= idx < N:
            c = grid.hexes[idx].center
            svg += _range_label(g, c.x, c.y, t0, t1, flag.comp)

    return svg


