@patch
def sight_overlay(self: PieceBoard, pieces: list[Piece],
                  elevation_mult: float = 0.005,
                  opacity: float = 0.35,
                  facing_only: bool = False,
                  color_attr: str = "darkPrimary"
                  ) -> str:
    """Dotted sight-range overlay, one color per kingdom."""
    svg = ""
    r = self.grid.radius
    dot_r   = max(2.5, r * 0.18)
    spacing = max(5.0, r * 0.32)
    grid = self.grid

    # Group visible hexes by kingdom flag
    flag_hexes: dict[str, tuple[CountryFlag, set[int]]] = {}
    for piece in pieces:
        if not piece.flag:
            continue
        key = piece.flag.name
        visible = piece.hexes_in_sight(
            grid, self.elevations,
            elevation_mult=elevation_mult,
            facing_only=facing_only
        )
        if key not in flag_hexes:
            flag_hexes[key] = (piece.flag, set())
        flag_hexes[key][1].update(visible)

    N = len(grid.hexes)
    for key, (flag, hex_indices) in flag_hexes.items():
        color = getattr(flag, color_attr, "#888")
        pat_id = f"sight_{key}"

        # Dot-fill pattern via SVGDef (proper <pattern> tag)
        dot = (f'<circle cx="{spacing/2:.1f}" cy="{spacing/2:.1f}" '
               f'r="{dot_r:.1f}" fill="{color}"/>')
        grid.builder.add_definition(SVGDef(
            "pattern", pat_id, dot,
            x="0", y="0",
            width=f"{spacing:.1f}", height=f"{spacing:.1f}",
            patternUnits="userSpaceOnUse",
        ))

        # Overlay style: dot-filled with dashed border
        sight_style = StyleCSS(
            f"sight_{key}",
            fill=f"url(#{pat_id})",
            opacity=str(opacity),
            stroke=color,
            stroke_width="0.8",
            stroke_dasharray="3,2",
            stroke_opacity="0.5",
        )
        grid.builder.add_style(sight_style)

        for idx in sorted(hex_indices):
            if 0 <= idx < N:
                h = grid.hexes[idx]
                svg += "\t" + Hex(h.radius, h.center, sight_style, v=h.v).svg() + "\n"

    return svg


