def SquadPlanOverlay(num_turns=5, **kw) -> OverlaySpec:
    """Patrol-plan overlay for all pieces across squads in ctx.squads.

    Renders ghost pieces, dashed arrows, rotation arcs, and harvest icons
    for every piece with instructions set.

    Context used (GameContext):
        ctx.squads          — list of Squad objects
        ctx.grid / ctx.terrain — render grid (may be zoomed)
        ctx.board           — coarse grid for simulation (falls back to ctx.grid)
        ctx.c2f             — coarse-to-fine index mapping for zoomed views
    """

    def render(ctx) -> str:
        grid = ctx.grid
        c2f  = ctx.extras.get('c2f')

        # Simulate on coarse grid when a board is available
        board = ctx.board
        if board is not None:
            sim_grid = board.terrain.hexGrid
            sim_elev = board.terrain.elevations
            sim_ctry = board.terrain.fields.get("country")
        else:
            sim_grid = grid
            sim_elev = ctx.terrain.elevations
            sim_ctry = ctx.terrain.fields.get("country")

        parts = []
        for squad in ctx.squads:
            pieces = squad.alive if hasattr(squad, 'alive') else squad.pieces
            for piece in pieces:
                if not piece.instructions or not piece.instructions.rules:
                    continue
                steps, _ = piece.plan_region(
                    sim_grid, sim_elev,
                    num_turns=num_turns, padding=0,
                    countries=sim_ctry,
                )
                if c2f is not None:
                    steps = [s for s in steps if s.hex_idx in c2f]
                parts.append(
                    piece_plan_overlay(piece, grid, steps=steps, c2f=c2f)
                )

        return '\n'.join(parts)

    return OverlaySpec("squad_plan", render, requires={'squads'}, priority=70)


# %% ../../nbs/game/04_piece.ipynb #b7718875
def PiecePlanOverlay(num_turns=5, ghost_opacity=0.4, **kw) -> OverlaySpec:
    """Movement plan overlay for all pieces in ctx.pieces.

    Draws dashed arrows, ghost pieces, action glyphs (harvest/defend/settle),
    and turn-range labels for every piece that has instructions set.

    Uses flag.piece_svg(size='board') for ghosts — same drawing pipeline as
    PieceOverlay — so pieces look consistent everywhere. Ghost IDs are unique
    per step to avoid duplicate SVG id issues.

    Does NOT draw the piece at its current position (PieceOverlay handles
    that at priority 80). Only draws the start_marker circle underneath.

    Priority 75 — below PieceOverlay (80), above terrain/rivers.
    """

    def render(ctx) -> str:
        if not ctx.pieces:
            return ""

        grid = ctx.grid
        c2f  = getattr(ctx, 'c2f', None)
        N    = len(grid.hexes)
        r    = grid.radius

        # Simulate on coarse board grid when available
        board = getattr(ctx, 'board', None)
        if board is not None:
            sim_grid = board.terrain.hexGrid
            sim_elev = board.terrain.elevations
            sim_ctry = board.terrain.fields.get("country")
        else:
            sim_grid = grid
            sim_elev = ctx.terrain.elevations
            sim_ctry = ctx.terrain.fields.get("country")

        ghost_scale = r * 0.55 / 22.5   # smaller than PieceOverlay's 0.8

        parts = []

        for piece in ctx.pieces:
            if not piece.instructions or not piece.instructions.rules:
                continue
            flag = piece.flag
            if flag is None:
                continue

            pid8 = piece.id[:8]

            # ── Glyph set + arrow style for this piece ──
            g = DiagramGlyphs(flag, size=r * 0.45)
            g.register_styles(ctx.builder)

            arrow_style = StyleCSS(
                f"plan_arr_{pid8}",
                stroke=flag.primary, stroke_width=max(1, r * 0.08),
                fill="none", opacity="0.7",
                stroke_dasharray=f"{r*0.25:.0f},{r*0.12:.0f}",
            )
            ctx.builder.add_style(arrow_style)

            # ── Simulate ──
            steps, _ = piece.plan_region(
                sim_grid, sim_elev,
                num_turns=num_turns, padding=0,
                countries=sim_ctry,
            )
            if not steps:
                continue

            # ── Start marker (circle only — PieceOverlay draws the piece) ──
            start = _map_point(piece.location, c2f)
            if 0 <= start < N:
                parts.append(g.start_marker(grid.hexes[start].center))

            # ── Walk through steps ──
            prev_idx = start
            ghost_n  = 0
            for step in steps:
                idx = _map_point(step.hex_idx, c2f)
                if idx < 0 or idx >= N:
                    prev_idx = idx
                    continue
                c = grid.hexes[idx].center

                if step.instruction == Instruction.FORWARD and not step.blocked:
                    # Arrow from previous position
                    if 0 <= prev_idx < N and prev_idx != idx:
                        parts.append(grid.arrow(
                            prev_idx, idx, style=arrow_style, factor=0.3))

                    # Ghost piece via flag.piece_svg (board tier = solid fill)
                    ghost_n += 1
                    gpid = f"ghost_{pid8}_{ghost_n}"
                    svg_str, pat_def = flag.piece_svg(
                        piece.piece_type, MapCord(c.x, c.y),
                        scale=ghost_scale, size='board', piece_id=gpid,
                    )
                    if pat_def is not None:
                        ctx.builder.add_definition(pat_def)
                    parts.append(f'<g opacity="{ghost_opacity}">{svg_str}</g>')

                elif step.blocked:
                    parts.append(g.blocked_x(c))
                else:
                    fn = _ACTION_GLYPH.get(step.instruction)
                    if fn:
                        parts.append(fn(g, c))

                prev_idx = idx

            # ── Turn-end range labels ──
            for hex_idx, t0, t1 in _turn_end_labels(steps):
                idx = _map_point(hex_idx, c2f)
                if 0 <= idx < N:
                    lc = grid.hexes[idx].center
                    parts.append(_range_label(g, lc.x, lc.y, t0, t1, flag.comp))

        return '\n'.join(parts)

    return OverlaySpec("piece_plan", render, requires={'pieces'}, priority=75)


# %% ../../nbs/game/04_piece.ipynb #66c4a83d
def SquadVisionOverlay(num_turns=5, facing_only=True,
                       opacity=0.30, color_attr="darkPrimary",
                       elevation_mult=0.005, **kw) -> OverlaySpec:
    """Vision cones + facing bars at each piece's simulated final position.

    Reads squads from ctx.squads (GameContext). No longer takes squads
    as a closure parameter — the same overlay spec works when squads
    change between renders.
    """

    def render(ctx) -> str:
        squads = ctx.squads
        if not squads:
            return ""

        grid    = ctx.grid
        builder = ctx.builder
        c2f     = ctx.extras.get('c2f')

        board = ctx.board
        if board is not None:
            sim_grid = board.terrain.hexGrid
            sim_elev = board.terrain.elevations
            sim_ctry = board.terrain.fields.get("country")
        else:
            sim_grid = grid
            sim_elev = ctx.terrain.elevations
            sim_ctry = ctx.terrain.fields.get("country")

        # ── helper: coarse index → list of fine indices ──
        def _c2f_list(idx):
            if c2f is None:
                return [idx]
            val = c2f.get(idx)
            if val is None:
                return []
            return val if isinstance(val, list) else [val]

        def _c2f_first(idx):
            mapped = _c2f_list(idx)
            return mapped[0] if mapped else -1

        # ── Simulate to collect final positions ──
        flag_hexes: dict[str, tuple[object, set[int]]] = {}
        bars: list[tuple[int, int, object]] = []

        r       = grid.radius
        dot_r   = max(2.5, r * 0.18)
        spacing = max(5.0, r * 0.32)
        N       = len(grid.hexes)

        for squad in squads:
            pieces = squad.alive if hasattr(squad, 'alive') else squad.pieces
            for piece in pieces:
                if not piece.instructions or not piece.instructions.rules:
                    continue
                if not piece.flag:
                    continue

                steps, _ = piece.plan_region(
                    sim_grid, sim_elev,
                    num_turns=num_turns, padding=0,
                    countries=sim_ctry,
                )
                if not steps:
                    continue

                last = steps[-1]
                key  = piece.flag.name

                elev      = max(0, sim_elev[last.hex_idx])
                eff_sight = int(piece.sight + elev * elevation_mult)

                if facing_only:
                    facing_dir = HexPosition.directions()[last.facing % 6]
                    fov = HexPosition.origin().field_of_view(facing_dir, eff_sight)
                    visible = [idx for hp in fov
                               if (idx := sim_grid.hexposition_to_index(hp, last.hex_idx)) >= 0]
                else:
                    visible = sim_grid.indices_in_range(last.hex_idx, eff_sight)

                if c2f is not None:
                    visible    = [fi for v in visible for fi in _c2f_list(v) if fi >= 0]
                    render_idx = _c2f_first(last.hex_idx)
                else:
                    render_idx = last.hex_idx

                if key not in flag_hexes:
                    flag_hexes[key] = (piece.flag, set())
                flag_hexes[key][1].update(visible)

                if 0 <= render_idx < N:
                    bars.append((render_idx, last.facing, piece.flag))

        # ── Render vision hex fills ──
        parts = []

        for key, (flag, hex_indices) in flag_hexes.items():
            color  = getattr(flag, color_attr, "#888")
            pat_id = f"vision_{key}"

            dot = (f'<circle cx="{spacing/2:.1f}" cy="{spacing/2:.1f}" '
                   f'r="{dot_r:.1f}" fill="{color}"/>')
            builder.add_definition(SVGDef(
                "pattern", pat_id, dot,
                x="0", y="0",
                width=f"{spacing:.1f}", height=f"{spacing:.1f}",
                patternUnits="userSpaceOnUse",
            ))

            vis_style = StyleCSS(
                f"vision_{key}",
                fill=f"url(#{pat_id})",
                opacity=str(opacity),
                stroke=color,
                stroke_width="0.6",
                stroke_dasharray="3,2",
                stroke_opacity="0.4",
            )
            builder.add_style(vis_style)

            for idx in sorted(hex_indices):
                if 0 <= idx < N:
                    h = grid.hexes[idx]
                    parts.append(Hex(h.radius, h.center, vis_style, v=h.v).svg())

        # ── Render facing bars via DiagramGlyphs ──
        for render_idx, facing, flag in bars:
            c = grid.hexes[render_idx].center
            glyphs = DiagramGlyphs(flag, size=r * 0.7)
            glyphs.register_styles(builder)
            parts.append(glyphs.facing_bar(c, facing))

        return '\n'.join(parts)

    return OverlaySpec("squad_vision", render, requires={'squads'}, priority=65)


# %% ../../nbs/game/04_piece.ipynb #4eb45140
def SquadSymbolOverlay(size='board', font='Cinzel',
                       label_offset=22, show_label=True, **kw) -> OverlaySpec:
    """Draw each squad's animal symbol at its centroid with a name label beneath.

    Reads squads from ctx.squads (GameContext). No longer takes squads
    as a closure parameter — the same overlay spec works when squads
    change between renders.

    Args:
        size:         animal_svg size — 'board', 'list', or 'large'
        font:         font family for labels (loaded via add_font)
        label_offset: vertical px offset for label below symbol center
        show_label:   whether to render the text label

    Context used (GameContext):
        ctx.squads          — list of Squad objects
        ctx.grid / ctx.builder — render grid
        ctx.board           — coarse grid for centroid calc (optional)
        ctx.c2f             — coarse→fine mapping for zoomed views (optional)
    """

    def render(ctx) -> str:
        squads = ctx.squads
        if not squads:
            return ""

        grid    = ctx.grid
        c2f     = getattr(ctx, 'c2f', None)
        board   = ctx.board
        sim_grid = board.terrain.hexGrid if board else grid

        ctx.builder.add_font(font)

        parts = []
        for i, squad in enumerate(squads):
            pieces = squad.alive if hasattr(squad, 'alive') else squad.pieces
            if not pieces:
                continue

            center_idx, _ = pieces_center(pieces, sim_grid)
            if center_idx < 0:
                continue

            # Map coarse → fine for zoomed views
            render_idx = _map_point(center_idx, c2f)
            if render_idx < 0 or render_idx >= len(grid.hexes):
                continue

            center = grid.hexes[render_idx].center
            flag   = squad.flag
            if flag is None:
                continue

            # ── Animal symbol ──
            sid = f"sq_{squad.id}_{i}"
            parts.append(flag.animal_svg(size=size, center=center, piece_id=sid))

            # ── Label ──
            if show_label:
                label = squad.name or squad.animal or ""
                if not label:
                    continue
                lbl_style = flag.labelStyle(f"sql_{squad.id}_{i}")
                ctx.builder.add_style(lbl_style)
                parts.append(
                    f'<text x="{center.x}" y="{center.y + label_offset}" '
                    f'text-anchor="middle" font-size="11" '
                    f"font-family=\"'{font}', serif\" "
                    f'dominant-baseline="hanging" '
                    f'class="{lbl_style.name}">{label}</text>'
                )

        return '\n'.join(parts)

    return OverlaySpec("squad_symbols", render, requires={'squads'}, priority=75)


