    def __init__(self,radius = 20, useKoreanMap = False):
        if useKoreanMap:
            self.terr = TerraDemo().japan_korea_map()#.shrinkWeather()
        else:
            world = TerrainFactory.create_world(
                bounds= MapRect(MapCord(0, 0), MapSize(300, 300)),
                preset='temperate',
                name='Maiden Lane',
                radius=15,
                lon_span=10.0,
                num_plates=8,
                subdivisions=3,
                ocean_fraction=0.3,
                oceanic_sides=['N'],  # Ocean on east and west
                terrain_age='young',  # Sharp, dramatic features
                formation_type='ridge',  # Creates ridge formations
                elevation_scale=1.5,  # Exaggerate the heights
                erosion_age=0.1,  # Minimal erosion for sharp peaks
                num_lakes=0,
                seed=23,
                debug=True
            )

            self.terr  = world.terrain
        #self.terr.repalete()
        self.grid = self.terr.hexGrid
        self.grid.adjustRadius(radius)
        rivers = self.terr.carve_to_ocean(num_lakes=0)
        self.builder = self.grid.builder

        self.board = GameBoard(self.terr,2) # palette_name = "Spectral")
        self.basin = DrainageBasins(self.terr)
        
        self.country = self.board .kingdoms[0]
        self.home = self.country.settlements[0]
        self.squads = Squad.squads(6,self.country.flag)
        self.queenGuard = self.squads[0]
        for pType in [PieceType.PAWN,PieceType.PAWN,PieceType.PAWN,PieceType.PAWN,PieceType.PAWN,PieceType.QUEEN]:
            piece = self.home.recruit(pType,flag=self.queenGuard.flag)
    #FoodProfile.apply(piece)
            self.queenGuard.pieces.append(piece)

        
        self.home.place_squad_spiral(self.queenGuard,self.terr)
        self.queen = self.queenGuard.by_rank()[0]

    def clearTerr(self):
        self.builder.layers = []

    def region(self):
        return HexRegion(hexes=set(self.terr.ring(self.queen.location, 5)), hexGrid=self.grid)




